{"query":"{
  Package(name: $package) {
    symbols {
      name @filter(op: "=", value: ["$name"])
      referencedBy {
        name @output
        kind @output
        signature @output
      }
    }
  }
}","variables":{"name":"search_slice_with_raw","package":"memchr"}}

